<script lang="ts">
  import type {Database,DatabaseViewConfig,Page,PropertyValue} from "@/features/notion-ui/variants/database/types"; import {groupBy} from "@/features/notion-ui/variants/database/lib/viewData"; import {selectGroupProp,visibleProps} from "../../lib/view-core"; import PropertyCell from "../PropertyCell.svelte";
  let {db,view,rows,readOnly=false,pages=[],onRowUpdate,onOpenRow,onRowAddInGroup}= $props<{db:Database;view:DatabaseViewConfig;rows:Page[];readOnly?:boolean;pages?:Page[];onRowUpdate?:(r:string,p:string,v:PropertyValue)=>void;onOpenRow?:(id:string)=>void;onRowAddInGroup?:(a:{groupPropId:string;groupValue:string|null})=>void}>();
  let groupProp=$derived(selectGroupProp(db,view)),props=$derived(visibleProps(db,view).filter((p)=>p.id!==groupProp?.id).slice(0,3)),groups=$derived(groupProp?groupBy(rows,groupProp):[{key:null,label:"Rows",color:"muted",rows}]);
</script>
<div class="flex gap-3 overflow-x-auto p-3">{#each groups as group (group.key??"none")}<section class="w-72 shrink-0 rounded-lg bg-muted/25 p-2"><header class="mb-2 flex items-center justify-between text-xs font-semibold"><span>{group.label}</span><span class="text-muted-foreground">{group.rows.length}</span></header><div class="space-y-2">{#each group.rows as row (row.id)}<article class="rounded-lg border bg-background p-3 shadow-sm"><button class="mb-2 block w-full truncate text-left text-sm font-medium" onclick={()=>onOpenRow?.(row.id)}>{row.icon} {row.title||"Untitled"}</button>{#each props as prop (prop.id)}<div class="grid grid-cols-[80px_1fr] items-center gap-1"><span class="truncate text-[10px] text-muted-foreground">{prop.name}</span><PropertyCell {prop} value={row.rowProps?.[prop.id]} {row} {db} {pages} {readOnly} onChange={(v)=>onRowUpdate?.(row.id,prop.id,v)}/></div>{/each}</article>{/each}</div>{#if !readOnly&&groupProp&&onRowAddInGroup}<button class="mt-2 w-full rounded px-2 py-1 text-left text-xs text-muted-foreground hover:bg-muted" onclick={()=>onRowAddInGroup?.({groupPropId:groupProp!.id,groupValue:group.key})}>+ New</button>{/if}</section>{/each}</div>
